<script setup lang="ts">
import {computed,ref} from 'vue'
import {useAuthStore} from '@/stores/auth'
import {strategyAdminCommand} from '@/services/strategy-admin'
const props=defineProps<{data:any;campaign:any;busy:boolean;initialQuadrant?:string}>(),emit=defineEmits<{command:[fn:()=>Promise<any>]}>(),auth=useAuthStore()
const states:Record<string,string>={not_started:'Não iniciou',in_progress:'Em curso',completed:'Concluído',exception:'Concluído com exceção'}
const people=computed(()=>(props.data.participation||[]).filter((r:any)=>r.campaign_id===props.campaign.id))
const mine=computed(()=>people.value.find((r:any)=>r.user_id===auth.profile?.id))
const reasons=ref<Record<string,string>>({}),importText=ref(''),importResult=ref<any>(null),quadrant=ref(props.initialQuadrant||'strengths')
const quadrants:Record<string,string>={strengths:'Forças',weaknesses:'Fraquezas',opportunities:'Oportunidades',threats:'Ameaças'}
function exception(p:any){emit('command',()=>strategyAdminCommand('participation_exception',props.campaign.id,{user_id:p.user_id,reason:reasons.value[p.user_id]||'Sem mais contributos relevantes identificados'}))}
const norm=(s:string)=>s.trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()
function importRows(){emit('command',async()=>{
 const entries=importText.value.split(/\r?\n/).filter(line=>line.trim()).map(line=>{
  const [text='',area='',scope='',team='',email='',q='']=line.split('\t')
  const thematic_area_id=props.data.strategy_thematic_areas?.find((a:any)=>norm(a.name)===norm(area))?.id
  const contribution_scope=({'propria equipa':'own_team','minha equipa':'own_team','equipa representada':'own_team','organizacao':'organization','samsys':'organization','corporativa':'organization','outra equipa':'other_team'} as Record<string,string>)[norm(scope)]||scope.trim()
  const team_id=team.trim()?props.data.teams?.find((t:any)=>norm(t.name)===norm(team))?.id||'invalid':null
  const explicit=q.trim()?Object.keys(quadrants).find(k=>norm(k)===norm(q)||norm(quadrants[k]!)===norm(q))||'invalid':undefined
  return {contribution:text,thematic_area_id,contribution_scope,team_id,author_email:email.trim()||undefined,quadrant:explicit}
 })
 importResult.value=await strategyAdminCommand('contribution_import',props.campaign.id,{entries,quadrant:quadrant.value})
 // Retain only failed lines so retrying cannot duplicate successful contributions.
 const lines=importText.value.split(/\r?\n/).filter(x=>x.trim());importText.value=importResult.value.errors.map((e:any)=>lines[e.line-1]).join('\n')
})}
</script>
<template><section class="sq-card p-3 mb-3"><h2 class="h5">Progresso por contexto</h2><p>Recomendação de 3 a 5 contributos por equipa representada e um único bloco corporativo. Propostas para outras equipas são opcionais e não completam os blocos obrigatórios.</p><div v-if="mine" class="mb-3"><span class="sq-state-pill" :data-state="mine.state">{{states[mine.state]}}</span><p v-if="mine.completion?.exception_reason" class="mt-2 mb-0">{{mine.completion.exception_reason}}</p></div><div v-if="mine" class="row g-3"><div v-for="c in mine.contexts" :key="c.team_id||'corporate'" class="col-md-4"><div class="sq-progress-context" :class="{'is-complete':!c.remaining}"><strong>{{c.label}}</strong><div class="fs-4 my-2">{{c.realized}} <small class="fs-6">/ {{c.recommended}} recomendados</small></div><progress :value="Math.min(c.realized,c.recommended)" :max="c.recommended" :aria-label="'Progresso de '+c.label"></progress><div class="small">Máximo {{c.max}} · {{c.remaining?c.remaining+' por completar':'Recomendação cumprida'}}</div></div></div></div><p v-else class="sq-muted">Os contextos são preparados na abertura para os participantes selecionados. Se não constas da lista, acompanha a campanha através do painel de coordenação.</p></section>
<section v-if="auth.canManageStrategy" class="sq-card p-3 mb-3"><h2 class="h5">Acompanhamento dos participantes</h2><div class="table-responsive"><table class="sq-table"><thead><tr><th>Participante</th><th>Contextos e pendências</th><th>Estado</th><th>Conclusão</th></tr></thead><tbody><tr v-if="!people.length"><td colspan="4">Seleciona os participantes e abre a campanha para preparar os contextos.</td></tr><tr v-for="p in people" :key="p.user_id"><td>{{p.name}}</td><td><div v-for="c in p.contexts" :key="c.team_id||'corporate'">{{c.label}}: {{c.realized}}/{{c.recommended}} · {{c.remaining?c.remaining+' por completar':'Cumprido'}}</div></td><td><span class="sq-state-pill" :data-state="p.state">{{states[p.state]}}</span></td><td><template v-if="!p.completion&&['open','validation'].includes(campaign.status)"><label class="d-block">Motivo da exceção<input v-model="reasons[p.user_id]" class="form-control" placeholder="Sem mais contributos relevantes identificados" maxlength="2000"></label><button class="btn btn-outline-warning mt-2" :disabled="busy" @click="exception(p)">Concluir com exceção</button></template><template v-else-if="p.completion"><div>{{p.completion.exception_reason}}</div><small>{{data.profiles?.find((u:any)=>u.id===p.completion.authorized_by)?.full_name}} · {{new Date(p.completion.submitted_at).toLocaleString('pt-PT')}}</small></template></td></tr></tbody></table></div></section>
<details v-if="auth.canManageStrategy&&campaign.status==='open'" class="sq-card p-3 mb-3"><summary>Importar contributos em massa</summary><p class="mt-2">Cola linhas de uma folha de cálculo, sem cabeçalho: <strong>Texto · Área temática · Contexto · Equipa alvo · Email do autor · Quadrante</strong>. Separa as colunas com tabulações. Equipa é obrigatória nos contextos de equipa; autor e quadrante podem ficar vazios.</p><p>Contextos: Minha equipa, Organização ou Outra equipa. Sem autor, é usada a tua conta. Os autores indicados devem ser participantes existentes da campanha. As linhas válidas são guardadas; as inválidas ficam na caixa para correção.</p><label>Quadrante herdado<select v-model="quadrant" class="form-select"><option v-for="(label,key) in quadrants" :key="key" :value="key">{{label}}</option></select></label><textarea v-model="importText" class="form-control my-3" rows="5" aria-label="Linhas de contributos para importar"/><button class="btn btn-primary" :disabled="busy||!importText.trim()" @click="importRows">Validar e importar linhas</button><div v-if="importResult" class="mt-3" role="status"><p>{{importResult.imported.length}} linhas importadas · {{importResult.errors.length}} linhas por corrigir.</p><ul><li v-for="e in importResult.errors" :key="e.line">Linha {{e.line}}: {{e.message}}</li></ul></div></details>
</template>
